using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Arith.FibonacciAtomic.Observer.Acquisition;

internal sealed class NativeBoundedPreorderRowsDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Arith/FibonacciAtomic/Observer/Acquisition/NativeBoundedPreorderRows.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A finite binary path determines the complete pending preorder frontier.",
        H("Compressed preorder control"), Blocks(
            Paragraph(Text("A source is a nonempty finite ordered full binary tree with Boolean leaves. An address is a finite Boolean list, with false for left and true for right. Reports retain their addresses and four-valued replies in chronological order.")),
            Entry("rightsPending", "Pending right siblings", "For each left edge in p, take the prefix before that edge and append a right edge. List these addresses from the deepest such edge to the shallowest. The list describes the unvisited siblings mathematically; it is not a field of the cursor.", DescribeRole.Definition),
            Entry("nextPath", "Advance after a closed node", "Search for the last left edge of p. If it exists, replace it by a right edge and delete all subsequent edges. Otherwise return none. The recursion examines only p.", DescribeRole.Definition),
            Entry("pending", "The frontier represented by a cursor", "The cursor none represents the empty frontier. A cursor some(p) represents p followed by rightsPending(p).", DescribeRole.Definition),
            Entry("cursorStep", "One structural step", "A branch reply at p moves to p followed by a left edge. Every other reply moves to nextPath(p). Actual source traversal has no absent replies; handling absent as an error is a separate instruction rule.", DescribeRole.Definition),
            Entry("CursorRun", "Path-selected report sequences", "The empty sequence leaves its cursor unchanged. A nonempty sequence at some(p) must first report p, and its remaining reports start at cursorStep(p,r). The relation has no hidden tree, pending-subtree stack, or acquired history in its transition rule.", DescribeRole.Definition),
            Entry("ActualCursorPrefix", "Actual finite prefixes", "The initial cursor is some(empty address), with no reports. A cursor at p reads the actual source at p and advances by cursorStep. Histories label this relation and are not selector arguments.", DescribeRole.Definition),
            Entry("reachable_compressed_frontier_and_trial_simulation", "Exact actual preorder and compressed frontier", "For every source u, the complete acquisitionTrace([],u) is a CursorRun from some(empty address) to none. For every cursor c and history h reached by ActualCursorPrefix(u,c,h), h is a prefix of that complete trace, its existing acquisition frontier equals pending(c), and it is a CursorRun from the initial cursor to c. Further, for every decomposition of the complete trace as h followed by report a and suffix s, h is a CursorRun ending at some(a.address), its frontier is exactly a.address followed by rightsPending(a.address), and s is a CursorRun from cursorStep(a.address,a.reply) to none.", DescribeRole.Theorem),
            Paragraph(Text("The key address identity says that pending(nextPath(p)) is exactly rightsPending(p). Appending a left edge exposes its sibling before all earlier pending siblings. Thus a path step agrees with the independently defined acquisitionStep for every reply. The established actual acquisition execution then supplies the complete path-selected sequence. Induction on actual reads retains a suffix of that sequence, so every actual prefix has the same next query and the same pending queue.")),
            Entry("Mode", "Seven instruction modes", "The modes, in order, are VALUE, GUARD, POLL, UPDATE, HALT0, HALT1 and ERROR.", DescribeRole.Definition),
            Entry("Control", "Intermediate fields", "A control retains only its finite address p, its length s, the branch and leaf counts b and l, candidate index j, parity bit a, and mode mu. No source description or report history is a field.", DescribeRole.Definition),
            Entry("Parameters", "Installed constants", "One controller fixes the positive source size h, starting offset start, last candidate index last, polling literal depth pollDepth and whether the active polling modes are available.", DescribeRole.Definition),
            Entry("canonical", "Canonical exceptional controls", "A canonical control sets every field except the specified mode to zero or the empty address.", DescribeRole.Definition),
            Entry("fresh", "Fresh trial", "A fresh trial has root VALUE mode, the specified candidate index j, and zero length, counters and parity.", DescribeRole.Definition),
            Entry("queryMode", "Mode before a node query", "At offset zero or at the root, begin in VALUE. Otherwise begin in GUARD.", DescribeRole.Definition),
            Entry("Valid", "Field conditions", "Normal controls require s equal to the path length, s and b less than h, l at most h and j at most last. GUARD additionally requires positive offset and a nonempty path. POLL and UPDATE must be canonical and active. Halt and error controls must be canonical.", DescribeRole.Definition),
            Entry("virtualDelta", "Virtual node successors", "A virtual absent reply selects canonical ERROR. A branch reaching the h-th branch resets the trial and increments j if another candidate is available. Other branches descend left only within the path and branch bounds. A leaf increments l and updates parity; nextPath selects the next query. At the end, exactly l+1=h and b=h-1 select canonical HALT with the new parity bit. A saturated leaf counter or any failed condition selects ERROR.", DescribeRole.Definition),
            Entry("controlProgram", "Total source primitive rows", "VALUE reads p followed by halfCeil(start+j) right edges and applies decodeLabel followed by virtualDelta. GUARD reads the parent followed by floor((start+j)/2)+1 right edges; acceptance changes only its mode. POLL reads the installed right-ray literal: absent selects UPDATE, alpha starts candidate zero, and the other replies select ERROR. UPDATE performs one genuine update and returns to POLL. The two canonical halt modes halt; invalid controls and ERROR read the root and select canonical ERROR.", DescribeRole.Definition),
            Entry("alignmentBudget", "Even polling threshold", "For natural h and T, B=alignmentBudget(h,T)=2 halfCeil(T+2h). Thus B is even and at least T+2h.", DescribeRole.Definition),
            Entry("activeParameters", "The installed active constants", "The source size is h, the starting offset is B-2h+1, the last index is 2h-1, the polling depth is B/2, and active mode is enabled, where B=alignmentBudget(h,T).", DescribeRole.Definition),
            Entry("atPrefix", "Fields at a mathematical report prefix", "For candidate j, report prefix H, current address p and mode mu, this comparison control has path p, length equal to the length of p, branch and leaf counts of H, candidate j, and parity equal to the beta count of H modulo two. It is used to relate controls to traversal prefixes; the instruction rows do not evaluate it.", DescribeRole.Definition),
            Entry("TrialPoint", "Licensed compressed trial points", "A trial point has natural ghost offset N, candidate j, report prefix H, next report a and remaining reports tail. The installed offset start+j equals N, N is at most the stationary epoch tau, and j is within its installed range. The bounded trial is exactly H followed by a and tail. The prefix H belongs to the complete source traversal, its full pending frontier is a.address followed by rightsPending(a.address), and its branch and leaf counts and the current depth are less than h. The control is exactly atPrefix(j,H,a.address,mu), with mu either VALUE or the prescribed queryMode. These objects describe a mathematical relation and are not stored fields.", DescribeRole.Definition),
            Entry("RefinedRun", "Predicates along actual executions", "This finite execution relation has the same actual Read and Update steps as Run and additionally retains a mathematical predicate I at every configuration and epoch. Erasing these predicates gives a Run. If it ends at a Halt instruction, determinism ensures that every other finite Run from the same entry ends at a point satisfying I.", DescribeRole.Definition),
            Entry("native_one_update_alignment", "Actual one-Update alignment", "For all natural h,T,t and every source u with length(u)=h and t at most T, put B=alignmentBudget(h,T) and U=B-t-rightClock(u). Then U is positive, t+U=B-rightClock(u), and B-2h+1 is at most t+U at most B. The difference (t+U)-(B-2h+1) is at most 2h-1. There is an actual Run of controlProgram(activeParameters(h,T)), starting from canonical POLL at epoch zero on the entry source substitution iterated t times on u, reaching fresh candidate zero at epoch U. Each absent poll is followed by precisely one Update; the observer stores no poll count or absolute epoch. This alignment statement does not require parity of h or positivity of T.", DescribeRole.Theorem),
            Paragraph(Text("The source right clock is at most 2h-1. Its entry value is rightClock(u)+t, strictly below B. One genuine update increments it by one. Induction on the remaining difference to B builds the actual POLL, UPDATE, POLL execution, and the final poll is alpha. Only the fixed literal depth and short trial index range occur in the installed controls.")),
            Entry("native_stationary_bounded_execution", "Stationary bounded rows reach the original parity", "Fix parameters P, a natural epoch tau and sources u,y with length(u)=P.h and y equal to substitution iterated tau times on u. Assume P.start is at most tau, tau is at most P.start+P.last, and either P.h is even or tau is zero. For any observation field obs and epoch e whose replies at e are exactly readout on y, the independently defined controlProgram(P) has an actual Run from fresh(0) at e to the canonical original-parity Halt at e. That canonical control has a Halt instruction. Every actual Run from the same initial control and epoch which ends at a Halt instruction has this same final control and epoch. Every finite actual Run from that entry ends at epoch e, either at this final control or at a TrialPoint with its exact proper prefix, compressed frontier, bounded counters and licensed offset. The original parity bit is true exactly when the beta-leaf count of u is odd.", DescribeRole.Theorem),
            Entry("rowParameters", "Constants for all three regimes", "If active is true and T is positive, use activeParameters(h,T). Otherwise install size h, starting offset zero, last candidate T, polling depth zero and inactive mode. In particular T=0 always uses the direct traversal.", DescribeRole.Definition),
            Entry("rowInitial", "Common entry control", "For active mode and positive T, enter canonical POLL. For every other regime, enter fresh candidate zero. The entry is independent of the source and its historical epoch.", DescribeRole.Definition),
            Entry("rowUpdates", "Actual Update count", "For active mode and positive T, the number of genuine Updates on entry source substitution iterated t times on u is alignmentBudget(h,T)-t-rightClock(u). In the other regimes it is zero. This source-dependent number is mathematical comparison data, not stored control.", DescribeRole.Definition),
            Entry("RowPoint", "Actual intermediate configurations", "At source epoch a, a is at most the terminal Update count U. Either the installed parameters are active and the control is canonical POLL or UPDATE, or a equals U and the control is the canonical original-parity Halt or a TrialPoint in the stationary image at historical epoch tau.", DescribeRole.Definition),
            Entry("native_bounded_rows_execution", "Uniform actual bounded execution", "For all natural h,T,t and sources u with length(u)=h and t at most T, assume T=0 or h is even and choose either Boolean active setting. Let P=rowParameters(h,T,active), U=rowUpdates(h,T,t,u,active) and tau=t+U. Then P.start is at most tau at most P.start+P.last. Either U is zero, or it is positive and tau equals alignmentBudget(h,T)-rightClock(u). On the actual entry source substitution iterated t times on u, controlProgram(P) has a concrete Run from rowInitial(T,active) at source epoch zero to the canonical original-parity Halt at U. This is a Halt instruction, and every actual halt-ended Run from that entry has that same final control and source epoch. Every actual finite Run from the entry ends at a RowPoint(P,tau,u,U), so all trial points are stationary, licensed, and retain the exact compressed frontier and prefix counts.", DescribeRole.Theorem),
            Paragraph(Text("For two successive reports, the full frontier identities force the next path: a branch appends a left edge, and a leaf follows nextPath. Counts and parity agree with the extended prefix. A last branch is precisely a rejected trial and increments the candidate; a last leaf is precisely a complete traversal and satisfies the exact final leaf and branch tests. Licensed decoder replies turn these structural transitions into actual GUARD and VALUE Reads. Induction through each report list and backwards through the finite interval to its first complete candidate builds the concrete Run. The existing image theorem supplies each candidate before any decoder invocation, and the full-source parity theorem identifies its output. Determinism identifies every halt-ended Run.")),
            Paragraph(Text("The path correspondence and stationary execution statements do not specify a bit-field representation or a physical installed execution. Those require additional operational statements."))
        )));

    private static DocumentBlock Entry(string n, string title, string prose, DescribeRole role) => Describe.Lean(
        DescribeId.Create("nativeboundedpreorderrows-" + n.Replace("_", "-").ToLowerInvariant()),
        DeclarationHandle.Create(Prefix + n), H(title), StatementSource.WithoutFormula(),
        AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
}
